/// Looks up a GPUI method by its exact name (binary search over [`GPUI_METHODS`]).
pub fn lookup_gpui_method(name: &str) -> Option<&'static GpuiMethod> {
    GPUI_METHODS
        .binary_search_by(|m| m.name.cmp(name))
        .ok()
        .map(|index| &GPUI_METHODS[index])
}

